package com.inventory.skillgapanalysisbackend.dto;
import jakarta.validation.constraints.Email; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Size;
public class RegisterRequest { @NotBlank private String fullName; @Email @NotBlank private String email; @Size(min=8) private String password; private String role="STUDENT"; public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPassword(){return password;} public void setPassword(String v){password=v;} public String getRole(){return role;} public void setRole(String v){role=v;} }
